print_stmt_if_then_set(if_then_set(Var262,Val263,In265), T267) :- print_expr(Val263, 0, T264), print_rule_dsname(In265, T266), flatten([['if'], [Var262], ['='], T264, ['then'], ['set'], T266, [';']], T267).
