print_stmt_title(title(Text324), T326) :- print_expr(Text324, 0, T325), flatten([['title'], T325, [';']], T326).
print_stmt(T, Texts) :- print_stmt_title(T, Texts), !.

print_stmt_empty(empty, T327) :- flatten([[';']], T327).
